{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "국가유공자 우선주차구획에 국가유공자 본인 소유 차량을 가족이 단독으로 운전하여 주차할 수 있는지 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "국가유공자 본인 소유 차량이라도 국가유공자 본인이 탑승하지 않은 상태에서는 우선주차구획을 이용할 수 없습니다. 조례 제25조의5 제2항은 국가유공자 등 우선주차구획을 국가유공자 등이 차량에 탑승하였을 때 이용할 수 있다고 정하고 있습니다. 따라서 아버지만 국가유공자이고 자녀가 혼자 운전하여 탑승자가 없으면 이 구획에 주차할 수 없습니다.",
          "b_ids": "주차장:제25조의5제2항, 주차장:제25조의5제2항제1호, 주차장:제25조의5제2항제2호"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
